"""Populate the author-review paper from saved measured tables, never hand-entered scores."""
from .report_helpers import *

def ci(r,key='ci95'):
 return '['+', '.join(pp(x) for x in r[key])+']'
def main():
 resources=read(HERE/'tables/RESOURCES.json'); rt=resources['totals']
 resource_text=(f"Actual stage execution used {rt['model_calls']:,} local generation calls and {resources['stage_hours']:.3f} RunLedger reserved GPU-hours, including loading, profiling, failures and format repairs. The complete compatibility rollout used 2,816 calls and {resources['compatibility_hours']:.3f} hours. The conservative full exclusive handoff window, including dispatch and mirroring gaps, was {resources.get('exclusive_handoff_window_hours',0):.3f} hours. Input/output token totals were {rt['input_tokens']:,}/{rt['output_tokens']:,}; peak device allocation was {resources['peak_vram_bytes']/1024**3:.2f} GiB, including the inference engine's cache reservation. These quantities are not billed pod uptime. No training or paid API calls were added.")
 (HERE/'paper/resource_paragraph.tex').write_text(resource_text+'\n')
 counts=read(HERE/'tables/CORE_COUNTS.json');contrasts=read(HERE/'tables/CORE_CONTRASTS.json');cal=read(HERE/'reports/HOLDOUT_CALIBRATION.json');assert len(cal)==14
 sem=read(HERE/'tables/SEMANTIC_RATES.json');probes=read(HERE/'tables/STABILITY.json');quality=read(HERE/'tables/JUDGMENT_QUALITY.json');repairs=read(HERE/'tables/REPAIR_INTEGRITY.json')
 def cr(model,c):return next(x for x in contrasts if x['model']==model and x['comparison']=='C5-'+c)
 def sr(model,c,stratum,dim='authorization_assertion'):return next(x for x in sem if x['population']=='broad' and x['model']==model and x['condition']==c and x['stratum']==stratum and x['dimension']==dim)
 q,p=cr('qwen','C3'),cr('phi','C3')
 passes={m:[r['dimension'].replace('_',' ') for r in cal if r['model']==m and r['screen_pass']] for m in ['phi','qwen']}
 core_rows=[]
 for model in ['qwen','phi']:
  cs=['base','C1','C2','C3','C4','C5','C6','A1','A2','A3'] if model=='qwen' else ['base','C1','C3','C5']
  for c in cs:
   values=[]
   for seed in [17,29,43]:
    match=[r for r in counts if r['model']==model and r['condition']==c and r['seed']==seed]
    values.append(str(match[0]['paired_successes']) if match else ('same reference' if c=='base' else 'pending'))
   core_rows.append([model.capitalize(),c,*values])
 (HERE/'paper/core_table.tex').write_text(latex_table(['Model','Condition','Seed 17','Seed 29','Seed 43'],core_rows,'llrrr'))
 # Broad classifications are diagnostic measurements, not true semantic prevalence.
 sem_rows=[]
 for m in ['phi','qwen']:
  for c in ['C3','C5','A1']:
   cells=[]
   for s in ['direct','communication']:
    r=sr(m,c,s);cells.append(f"{r['yes']}/{r['planned']}")
   for dim in ['evidence_challenge','acknowledges_user_conflict']:
    r=sr(m,c,'communication',dim);cells.append(f"{r['yes']}/{r['planned']}")
   sem_rows.append([m.capitalize(),c,*cells])
 (HERE/'paper/semantic_table.tex').write_text(latex_table(['Judge','Condition','A-direct','A-comm','E-comm','C-comm'],sem_rows,'llrrrr'))
 ps=[]
 for m in ['phi','qwen']:
  for probe in ['alias_permutation','category_order','api_exposed']:
   r=next(r for r in probes if r['model']==m and r['probe']==probe and r['dimension']=='authorization_assertion');ps.append([m,probe.replace('_',' '),f"{r['changed']}/{r['jointly_assessed']}",str(r['baseline_missing']),str(r['probe_missing'])])
 (HERE/'paper/probe_table.tex').write_text(latex_table(['Judge','Probe','Changed / joint','Base missing','Probe missing'],ps,'llrrr'))
 controlled=read(HERE/'tables/COMPATIBILITY_PRIMARY_RESPONSE.json')
 controlled_semantics=[]
 for m in ['phi','qwen']:
  for arm in ['compatible','incompatible']:
   rr=next(r for r in sem if r['population']=='compatibility' and r['model']==m and r['condition']==arm and r['dimension']=='recipient_response')
   controlled_semantics.append([m.capitalize(),arm,str(rr['planned']),str(rr['label_counts'].get('continuation',0)),str(rr['label_counts'].get('new_position',0)),str(rr['missing'])])
 (HERE/'paper/controlled_semantic_table.tex').write_text(latex_table(['Judge','Arm','All','Continue','New position','Missing'],controlled_semantics,'llrrrr'))
 (HERE/'paper/interaction_table.tex').write_text(latex_table(['Next observable category','Compatible','Incompatible'],[[r['category'].replace('component_','').replace('_',' '),str(r['compatible_count']),str(r['incompatible_count'])] for r in controlled],'lrr'))
 changed=sum(bool(r['changed_dimensions']) for r in repairs);comparable=sum(r['comparable_dimensions']>0 for r in repairs)
 validrepair=f'{len(repairs)} format repairs; {changed}/{comparable} repairs with at least one recoverable original dimension changed a label'
 lines=[r'\section{Results}',r'\subsection{Action channels differ; semantic functions cannot be read from API names}',r'Across the common-base round-zero population, each condition contributes 900 episodes and 10,800 allocated opportunities from 150 unique paired families and three generator seeds. C3 makes 5,408 direct edits, versus 477 for C5 and 938 for A1. C5 instead uses 4,618 recollection actions, versus 828 for C3 and 1,397 for A1; A1 uses 4,830 proposals, versus 1,930 for C5 and 969 for C3. These denominators retain invalid and rejected actions. Figure~\ref{fig:channels} shows API channels, not false-memory or deception rates.',r'The family/seed paired contrast in edit rate is $-45.66$ percentage points for C5--C3 (95\% interval $[-48.20,-43.06]$). The recollection difference is $+35.09$ points $[31.64,38.67]$. Relative to motive-only A1, C5 uses $+29.82$ points more recollection $[27.08,32.66]$ and $-26.85$ points fewer proposals $[-29.29,-24.40]$. These reproduce earlier mechanical findings. The generators share a backbone and initial defender, but their interventions generate different subsequent contexts.',r'\begin{figure}[t]\centering\includegraphics[width=\textwidth]{../figures/channels.pdf}\caption{Qwen common-base action channels. Counts beside bars; 10,800 allocated opportunities per condition, seeds 17/29/43. Peer routes and invalid/pass opportunities remain visible. These dependent raw counts have no action-level error bars.}\label{fig:channels}\end{figure}',r'Recollection and proposal both append notes in this implementation. Their physical effect therefore does not identify their proposition. Selected examples include recommendations inside recollections, assertions of official decisions, and criticism in generic C3. The more modest conclusion is a reproducible change in tool choice and framing opportunities; a population change in authorization claims requires a reliable semantic measure.',r'\subsection{Typed pursuit persists, while state consequences remain distinct}',r'C5 repeats an eligible consecutive direct slot/value goal in 4,831/5,224 transitions, versus 3,623/5,400 for C3 and 5,093/5,364 for A1. The matched family-mean C5--C3 difference is $+25.39$ points $[22.22,28.58]$; C5--A1 is $-2.48$ points $[-4.30,-0.69]$. Pooled transition proportions and family-mean contrasts have different weighting. Stable option-oriented objectives explicitly encourage persistence, and motive-only A1 is at least as repetitive on this typed measure. This does not establish coherence, flexible strategy development, or a benefit of biographies.',r'Immediate working-state changes occur on 3,830 C3, 286 C5, and 562 A1 opportunities, out of 10,800 per condition. Notes change on 7,418, 7,554, and 7,344 opportunities, respectively. Neither immediate state changes nor note additions are final task failures. Unavailable-reference counts are 1,220, 1,229, and 1,225; the C5--C3 difference is $+0.08$ points $[-1.17,1.35]$. Similar observed rates do not establish equivalence or semantic citation support.',r'\subsection{Automated semantics expose measurement limits}',r'Development timing selected the complete 15-family tier before research labels: 540 broader opportunities, 72 fixed historical events, and 80 held-out controls per judge. The broader sample has 90 opportunities per condition and stratum, preserving both worlds and three generator seeds. Thirty-family selection would have exceeded the conservative four-hour allocation. We did not expand the sample after observing faster controlled execution.',r'Table~\ref{tab:calibration} reports the held-out screen. Phi passes '+str(len(passes['phi']))+r'/7 dimensions; Qwen passes '+str(len(passes['qwen']))+r'/7. Phi passes: '+tex(', '.join(passes['phi']) or 'none')+r'. Qwen passes: '+tex(', '.join(passes['qwen']) or 'none')+r'. These are engineering results on authored controls, not validation on natural dialogue. A failing different-family assessor is retained rather than replaced by the more favorable model.',r'\begin{figure}[t]\centering\includegraphics[width=\textwidth]{../figures/calibration.pdf}\caption{Held-out binary calibration on 80 controls per judge. Expected uncertain/non-applicable cases have separate counts. Abstentions count as errors; passing additionally requires substantive coverage of at least .80.}\label{fig:calibration}\end{figure}',r'\begin{table}[t]\centering\small\input{semantic_table.tex}\caption{Automatically positive labels in the broader sample: A, user authorization; E, evidence challenge; C, explicit conflict with user instructions. Every denominator is 90 allocated opportunities. Direct and communication strata remain separate. These are assessor outputs, not validated semantic prevalence.}\label{tab:semantic}\end{table}',r'Qwen classifies 31/90 C5 communication statements as evidence challenges, versus 16/90 C3 and 14/90 A1. The C5--C3 classified-positive difference is $+16.67$ points $[8.89,26.67]$ under family resampling. Phi produces 1/90 versus 4/90, a difference of $-3.33$ points $[-7.78,1.11]$. Qwen labels explicit recognition of a user conflict on 0/90 C5, 8/90 C3, and 2/90 A1 communication opportunities. Zero positive classifications is not proof that the behavior is absent. Its recipient-response labels include 6/90 new-position cases for C5, 27/90 C3, and 21/90 A1, with 39/90, 24/90, and 26/90 unassessed respectively. Communication routes also differ: 74/90, 84/90, and 86/90 go to components in C5/C3/A1; the rest go to the answerer. Component-only and all-route tables are supplied separately. These model-specific readings do not replace the failed different-family screen or establish a semantic treatment effect.',r'Table~\ref{tab:semantic} presents each assessor separately. Missing dimensions, uncertainty, applicability, jointly assessed agreement, positive/negative agreement, conservative two-judge ranges, per-seed estimates, and the non-overlap sensitivity are released with the complete tables. A positive label can denote a true assertion; it is not automatically false authorization. Comparisons against the ledger remain conditional on unambiguous model extraction.',r'\begin{table}[t]\centering\scriptsize\input{probe_table.tex}\caption{Authorization-label changes on the fixed 36-event probe subset. Denominators require valid baseline and probe labels; missing counts remain separate. These repeated evaluations are not new independent events.}\label{tab:probes}\end{table}',r'Alias, category-list, and metadata probes change some judgments (Table~\ref{tab:probes}). The category probe reverses the explicit list, not the schema skeleton. Actual notes can already contain API words, and greedy execution may have numerical variation. Thus these are sensitivity diagnostics, not isolated estimates of all evaluator biases. Across research and probe runs, '+tex(validrepair)+r'. A format-only instruction does not guarantee unchanged interpretation; both versions are retained. No further prompt tuning or semantic retry was used.',r'\subsection{Preference compatibility changes matching, not demonstrated persuasion}',r'All 64 controlled conversations complete: 16 paired families, two arms, 32 turns, 12 actor opportunities, and 2,816 generation calls. Every reserved communication opportunity enters the primary response distribution (128 per arm; Table~\ref{tab:interaction}). All 64 episode inbox reconstructions agree with the recorded observations.',r'\begin{table}[t]\centering\small\input{interaction_table.tex}\caption{Primary controlled next-action categories per 128 allocated communication opportunities. Same-goal refers to typed slot/value matching, not semantic endorsement. Answerer-directed opportunities remain in the denominator.}\label{tab:interaction}\end{table}',r'Compatible preferences yield 107/128 subsequent same-goal actions, versus 0/128 under incompatibility. Incompatible preferences yield 111/128 different values for the same slot, versus 6/128 under compatibility. The incompatible-minus-compatible differences are $-83.59$ points $[-95.31,-69.53]$ for matching and $+82.03$ points $[67.97,93.75]$ for a different value. These family intervals are descriptive of the fixed rollout. This large difference is partly mechanical: compatible actors are instructed to prefer the same value. Among visible component messages, 77 compatible matching cases already matched before delivery; 29 lack a prior recipient position and one has an untyped/other prior position. Six different-value cases remain different. Under incompatibility, 89 different-value cases remain different, 22 lack a prior position, and four remain untyped. Neither arm contains an observed different-to-matching typed transition. These observations do not identify persuasion or the causal effect of delivery.',r'Secondary paired task success is 5/16 compatible versus 7/16 incompatible: $+12.5$ points for incompatibility, with a family interval $[-12.5,37.5]$. Correct decisive-field handling is 25/32 in each arm; preferred-option adoption in the following answer is 196/384 versus 189/384. Immediate state changes are 5/384 versus 0/384. These counts neither show equivalence nor establish a task benefit from conflict. A post-run compliance check also finds departures from configured motives: 372/384 valid typed compatible actions and 380/380 valid typed incompatible actions pursue the owned goal (four incompatible actions lack valid typed goals). The existing delivery/no-delivery review diagnostic remains unexecuted at this cutoff, so no causal communication claim is made.',r'\subsection{Trained-answerer outcomes remain mixed or unfavorable}',r'At the fixed cutoff, 181/241 core stages are complete. Thirty-seven eligible 64-turn evaluation cells cover 240 paired families each; all completed conditions and seeds are retained in Table~\ref{tab:core}. The remaining 60 stages are listed explicitly, including the last C6 evaluation and horizon, recovery, unfamiliar-input, external, and natural-language extensions. Later operational completions do not silently change this population.',r'For antagonist-free paired success, Qwen C5--C3 is '+tex(pp(q['difference']))+r' points, 95\% interval '+tex(ci(q))+r'; Phi C5--C3 is '+tex(pp(p['difference']))+r' points '+tex(ci(p))+r'. Both central estimates favor C3 and both intervals include zero. Qwen C5--C1 is '+tex(pp(cr('qwen','C1')['difference']))+r' points '+tex(ci(cr('qwen','C1')))+r', while Phi C5--C1 is '+tex(pp(cr('phi','C1')['difference']))+r' points '+tex(ci(cr('phi','C1')))+r'. These means conceal seed reversals. Qwen C5--A1 is '+tex(pp(cr('qwen','A1')['difference']))+r' points '+tex(ci(cr('qwen','A1')))+r', which does not establish a biography benefit.',r'\begin{figure}[t]\centering\includegraphics[width=\textwidth]{../figures/core_contrasts.pdf}\caption{Antagonist-free paired-success differences, 240 families and three training seeds per model. Intervals use the original two-way seed/family percentile bootstrap. Missing future evaluations are not imputed.}\label{fig:core}\end{figure}',r'Every completed C5 seed exceeds the untrained reference (67/240 paired families for Qwen; 27/240 for Phi). This improvement does not identify a character-specific training benefit: clean and generic training also improve on the base models. Original secondary comparisons retain their multiplicity treatment in the machine-readable tables. We do not reinterpret failed/null differences as equivalence. The behavioral archive, learned-answerer outcomes, and controlled preference experiment answer different questions; their aggregate association cannot identify a training mechanism.']
 (HERE/'paper/sections/results.tex').write_text('\n\n'.join(lines)+'\n')
 abstract=f'''Persistent component motives can change conversational behavior without improving task accuracy. We characterize a shared-backbone system with generic adversaries, biography-plus-motive components, and motive-only components. Across 150 paired synthetic planning families, three generator seeds, and 10,800 intervention opportunities per condition, biography-plus-motive components make 477 direct edits versus 5,408 for generic adversaries, while using 4,618 recollection actions versus 828. Typed preference repetition is high in both character and motive-only conditions, but API labels do not establish the meaning of a claim. We evaluate two frozen model-family assessors on 80 held-out synthetic controls each, 612 archive-sample records, 32 fresh controlled events, and stability probes. Phi passes {len(passes['phi'])} of seven declared screening dimensions and Qwen passes {len(passes['qwen'])}; semantic outputs remain separately reported, with calibration and natural-dialogue validity distinguished. A complete 64-conversation experiment changes compatible to incompatible same-field preferences. Typed matching changes sharply, but most matching follows an existing position; paired task success is 5/16 versus 7/16 families, with wide uncertainty. Antagonist-free C5-minus-generic accuracy differences are {pp(q['difference'])} and {pp(p['difference'])} percentage points for Qwen and Phi, respectively. Traceable dialogues support a bounded account of advocacy, evidence transport, and limited observable peer response. No independent human semantic annotations were collected.'''
 words=len(abstract.split());assert 150<=words<=250,words;(HERE/'paper/abstract.tex').write_text(abstract.replace('%',r'\%')+'\n');write(HERE/'reports/ABSTRACT.json',{'words':words,'minimum':150,'maximum':250})
 appendix=[r'\section{Complete core and calibration tables}',r'\begin{table}[H]\centering\small\input{core_table.tex}\caption{Paired successes out of 240 families per completed seed. The base model is one shared reference, not three replications. C2: random corruption; C4: two total components; C6: five; A2: no private history; A3: no peer interaction. C4/C5/C6 also differ in role composition and routing.}\label{tab:core}\end{table}',r'\begin{table}[H]\centering\scriptsize\resizebox{\textwidth}{!}{\input{calibration_table.tex}}\caption{Held-out screens. Score is balanced accuracy for binary dimensions and exact accuracy for categorical dimensions, with abstentions counted as failures. Coverage is substantive predictions/eligible controls; P/F denotes the prespecified screen, not natural-dialogue validation.}\label{tab:calibration}\end{table}',r'\section{Auxiliary controlled-event classifications}',r'\begin{table}[H]\centering\small\input{controlled_semantic_table.tex}\caption{Fixed 32-event controlled semantic sample, 16 events per arm per judge. These are automatically classified recipient responses, not verified persuasion.}\end{table}',r'The assessors disagree on continuation versus a new position and leave many responses unassessed. These semantic labels concern the text, whereas the primary controlled categories concern typed slot/value matching. They must not be merged into a single outcome. Calibration failures and the absence of a delivery intervention limit interpretation.',r'\section{Scope of reproducibility}',r'The companion evidence package includes exact judge inputs, raw outputs and repairs, selected reconstructed archive episodes, all controlled traces, compact family outcomes, model revisions, and executable analysis. It distinguishes selected-record verification from hashing entire original archives. Weights and credentials are excluded. Unit tests require no model; artifact integration uses the supplied compressed bundle. Numerical table reproduction does not establish the validity of semantic readings.',r'The final evaluation was prospectively frozen after one development prompt revision, within a retrospectively motivated characterization. A versioned analysis correction preserves planned missing judgments in denominators; an internal compact export correction distinguishes the evaluated adapter condition from the antagonist-free evaluation condition. Original scientific files and human forms are unchanged. No human labels, agreement values, or adjudications are fabricated.',r'The first Phi profiling attempt failed before any model call. The time-limited Qwen main attempt persisted 640 of 692 tasks; a separately frozen continuation executed only the 52 unrecorded IDs under unchanged inputs and settings. Thirty-two original generated outputs were not written before the time guard and are unavailable; their calls and tokens remain charged. Existing recorded judgments were never replaced because of their labels. These operational failures and both raw repair versions remain in the provenance.',r'\section{Remaining empirical questions}',r'The unexecuted review delivery intervention can test message availability under its declared controls. The completed compatible/incompatible intervention tests preference configuration. Neither substitutes for the other. Broader natural-language transfer and long-horizon evaluations are pending at the evidence cutoff. These omissions restrict the paper scope; they do not convert historical human recruitment into a requirement. Final scientific interpretation, authorship, disclosure, anonymity, and submission scope require human author review.']
 (HERE/'paper/appendix.tex').write_text('\n\n'.join(appendix)+r'\input{sections/appendix_methods.tex}'+r'\input{sections/controlled_dialogue.tex}'+'\n');print('Paper results and abstract generated:',words,'abstract words')
if __name__=='__main__':main()
